package com.immersio.practice.api; import com.immersio.practice.api.dto.*; import com.immersio.practice.service.*; import com.immersio.shared.dto.ApiResponse; import com.immersio.shared.security.JwtTokenProvider; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/practice") public class PracticeController {private final PronunciationService service; private final JwtTokenProvider jwt; public PracticeController(PronunciationService s,JwtTokenProvider j){service=s;jwt=j;} private UUID user(String h){return jwt.extractUserId(h.replace("Bearer ",""));}
 @PostMapping("/pronunciation-log") public ApiResponse<PronunciationLogDto> log(@RequestHeader("Authorization") String h,@RequestBody CreatePronunciationLogRequest r){return ApiResponse.successResult(service.logPronunciation(user(h),r));}
 @GetMapping("/pronunciation-history") public ApiResponse<List<PronunciationLogDto>> history(@RequestHeader("Authorization") String h){return ApiResponse.successResult(service.getUserLogs(user(h)));}
 @GetMapping("/cefr-analysis") public ApiResponse<CefrAnalysisDto> cefr(@RequestHeader("Authorization") String h){return ApiResponse.successResult(service.analyzeCefrLevel(user(h)));}
 @PostMapping("/generate-phrase") public ApiResponse<GeneratedPhraseDto> phrase(@RequestBody GeneratePhraseRequest r){return ApiResponse.successResult(service.generatePhrase(r));}
 @PostMapping("/dictionary-lookup") public ApiResponse<DictionaryEntryDto> dictionary(@RequestBody DictionaryLookupRequest r){return ApiResponse.successResult(service.lookupWord(r));}
 @PostMapping("/tts") public ApiResponse<Map<String,String>> tts(@RequestBody TtsRequest r){return ApiResponse.successResult(Map.of("text",r.text()==null?"":r.text(),"status","queued"));}}
